import { LightningElement, wire } from 'lwc';
import {
    MessageContext,
    APPLICATION_SCOPE,
    unsubscribe
} from 'lightning/messageService';
import Account_Selected from '@salesforce/messageChannel/Account_Selected__c';

export default class AccountDetailsPanel extends LightningElement {
    selectedAccountId;
    _messageContext;
    _subscriptionToken;

    @wire(MessageContext)
    setMessageContext({ value }) {
        if (value) {
            this._messageContext = value;
            // Ensure we never hold more than one subscription
            if (this._subscriptionToken) {
                unsubscribe(this._subscriptionToken);
            }
            this._subscriptionToken = value.subscribe(
                Account_Selected,
                (message) => this.handleAccountSelected(message),
                { scope: APPLICATION_SCOPE }
            );
        }
    }

    disconnectedCallback() {
        if (this._subscriptionToken) {
            unsubscribe(this._subscriptionToken);
            this._subscriptionToken = undefined;
        }
    }

    handleAccountSelected(message) {
        this.selectedAccountId = message.recordId;
    }

    handleClear() {
        if (this._messageContext) {
            this._messageContext.publish(
                Account_Selected,
                { recordId: null },
                { scope: APPLICATION_SCOPE }
            );
        }
    }

    get hasSelectedAccount() {
        return this.selectedAccountId != null;
    }
}
