import { LightningElement, api } from 'lwc';

let uid = 0;

export default class StatusListbox extends LightningElement {
    @api label;

    _value = '';
    _apiOptions = [];
    _activeIndex = 0;
    _idPrefix;

    constructor() {
        super();
        this._idPrefix = `status-listbox-${++uid}`;
    }

    @api
    get value() {
        return this._value;
    }

    set value(val) {
        const prev = this._value;
        this._value = val;
        if (val !== prev) {
            const idx = this._apiOptions.findIndex((o) => o.value === val);
            this._activeIndex = idx !== -1 ? idx : 0;
        }
    }

    @api
    get options() {
        return this._apiOptions;
    }

    set options(val) {
        this._apiOptions = val || [];
        const idx = this._apiOptions.findIndex((o) => o.value === this._value);
        this._activeIndex = idx !== -1 ? idx : 0;
    }

    get optionItems() {
        return this._apiOptions.map((opt, i) => ({
            ...opt,
            id: `${this._idPrefix}-option-${i}`,
            isSelected: opt.value === this._value
        }));
    }

    get activeDescendantId() {
        if (this._apiOptions.length === 0) {
            return null;
        }
        return `${this._idPrefix}-option-${this._activeIndex}`;
    }

    handleKeydown(event) {
        const { key } = event;
        const len = this._apiOptions.length;

        if (len === 0) {
            return;
        }

        switch (key) {
            case 'ArrowDown':
                event.preventDefault();
                if (this._activeIndex < len - 1) {
                    this._activeIndex++;
                }
                break;
            case 'ArrowUp':
                event.preventDefault();
                if (this._activeIndex > 0) {
                    this._activeIndex--;
                }
                break;
            case 'Home':
                event.preventDefault();
                this._activeIndex = 0;
                break;
            case 'End':
                event.preventDefault();
                this._activeIndex = len - 1;
                break;
            case 'Enter':
            case ' ':
                event.preventDefault();
                this._selectActive();
                break;
            default:
                break;
        }
    }

    handleOptionClick(event) {
        const target = event.currentTarget;
        this._selectOption(target.dataset.value);
    }

    _selectActive() {
        const opts = this._apiOptions;
        if (this._activeIndex >= 0 && this._activeIndex < opts.length) {
            this._selectOption(opts[this._activeIndex].value);
        }
    }

    _selectOption(value) {
        if (value === this._value) {
            return;
        }
        this._value = value;
        this._activeIndex = this._apiOptions.findIndex((o) => o.value === value);
        this.dispatchEvent(
            new CustomEvent('change', { detail: { value } })
        );
    }
}
