        return this.items.filter((t) => !t.done).length;
    }

    handleAdd() {
        const input = this.template.querySelector('.new-task');
        const rawLabel = input.value || '';
        const label = rawLabel.trim();
        if (!label) {
            return;
        }

        const id = `new-${this.nextId++}`;
        this.items = [...this.items, { id, label, done: false }];
        input.value = '';

        this.dispatchEvent(
            new CustomEvent('taskadded', { detail: { label } })
        );
    }

    handleToggle(event) {
        const id = event.target.dataset.id;
        this.items = this.items.map((t) =>
            t.id === id ? { ...t, done: !t.done } : t
        );
    }
}
