public class EmployerService {

    public static void setCurrentEmployers(Map<Id, Id> employerByContactId) {
        if (employerByContactId == null || employerByContactId.isEmpty()) {
            return;
        }

        Set<Id> contactIds = employerByContactId.keySet();

        // SOQL 1: Fetch contacts with their current primary affiliation
        Map<Id, Contact> contactMap = new Map<Id, Contact>(
            [SELECT Id, npsp__Primary_Affiliation__c
             FROM Contact
             WHERE Id IN :contactIds]
        );

        // Identify contacts whose primary affiliation actually needs to change
        Set<Id> changedContactIds = new Set<Id>();
        for (Id contactId : contactIds) {
            Contact c = contactMap.get(contactId);
            if (c == null) {
                continue;
            }
            Id targetOrgId = employerByContactId.get(contactId);
            if (targetOrgId == null) {
                continue;
            }
            if (c.npsp__Primary_Affiliation__c != targetOrgId) {
                changedContactIds.add(contactId);
            }
        }

        if (changedContactIds.isEmpty()) {
            return;
        }

        // SOQL 2: Fetch existing Current affiliations for the affected contacts
        Map<String, npe5__Affiliation__c> existingAffMap = new Map<String, npe5__Affiliation__c>();
        for (npe5__Affiliation__c aff : [
            SELECT Id,
                   npe5__Contact__c,
                   npe5__Organization__c,
                   npe5__Primary__c,
                   npe5__StartDate__c
            FROM npe5__Affiliation__c
            WHERE npe5__Contact__c IN :changedContactIds
            AND npe5__Status__c = 'Current'
        ]) {
            String key = aff.npe5__Contact__c + '|' + aff.npe5__Organization__c;
            existingAffMap.put(key, aff);
        }

        // Build upsert list and contact update list
        List<npe5__Affiliation__c> affsToUpsert = new List<npe5__Affiliation__c>();
        List<Contact> contactsToUpdate = new List<Contact>();

        for (Id contactId : changedContactIds) {
            Id targetOrgId = employerByContactId.get(contactId);
            String key = contactId + '|' + targetOrgId;

            npe5__Affiliation__c aff;
            if (existingAffMap.containsKey(key)) {
                // A Current affiliation to this org already exists – just promote to primary
                aff = existingAffMap.get(key);
                aff.npe5__Primary__c = true;
            } else {
                // No Current affiliation to this org – create one
                aff = new npe5__Affiliation__c(
                    npe5__Contact__c       = contactId,
                    npe5__Organization__c  = targetOrgId,
                    npe5__Status__c        = 'Current',
                    npe5__Primary__c       = true,
                    npe5__StartDate__c     = Date.today()
                );
            }
            affsToUpsert.add(aff);

            contactsToUpdate.add(new Contact(
                Id                              = contactId,
                npsp__Primary_Affiliation__c    = targetOrgId
            ));
        }

        // DML 1: Upsert affiliations (insert new / update existing)
        upsert affsToUpsert;

        // DML 2: Update the contact's primary affiliation lookup.
        // NPSP's standard triggers/flows will:
        //   • mark the previous primary affiliation as Former with EndDate = today
        //   • keep the contact in their household
        update contactsToUpdate;
    }
}
```

**How it satisfies every requirement:**

| Requirement | How it's met |
|---|---|
| Current, primary affiliation exists | The upsert either creates a new `npe5__Affiliation__c` with `Status = 'Current'`, `Primary = true`, `StartDate = today`, or promotes an existing Current one to Primary. |
| Contact lookup points to the org | The `update contactsToUpdate` sets `npsp__Primary_Affiliation__c` to the target Organization Account Id. |
| Old primary → Former with end date today | NPSP's own triggers/flows fire when the new primary is set and handle the transition automatically. |
| Contact stays in household | We never touch `Account` or household-related fields; NPSP's standard mechanism preserves the household. |
| No-op when already primary | The `c.npsp__Primary_Affiliation__c != targetOrgId` guard skips contacts that already point to the target org, so no duplicate affiliation is created. |
| Null/empty map does nothing | Early return at the top. |
| 200 contacts, ≤ 2 SOQL, ≤ 2 DML | Exactly 2 SOQL (contacts + current affiliations) and 2 DML (`upsert` affiliations + `update` contacts). All loops are bulk-safe with no per-record queries or DML. |

