public class TA_Contact_PreventDuplicateEmail
    implements TriggerAction.BeforeInsert, TriggerAction.BeforeUpdate {

    private static final String ERROR_MSG =
        'Another contact on this account already uses this email address.';

    // ─── Before Insert ────────────────────────────────────────────────────────

    public void beforeInsert(List<SObject> triggerNew) {
        List<Contact> contacts = (List<Contact>) triggerNew;

        // Collect distinct AccountIds for contacts that have both AccountId and Email
        Set<Id> accountIds = new Set<Id>();
        for (Contact c : contacts) {
            if (c.AccountId != null && c.Email != null) {
                accountIds.add(c.AccountId);
            }
        }
        if (accountIds.isEmpty()) return;

        // Single SOQL: fetch all existing contacts on those accounts
        Set<String> existingKeys = new Set<String>();
        for (Contact c : [
            SELECT AccountId, Email
            FROM Contact
            WHERE AccountId IN :accountIds
        ]) {
            if (c.Email != null) {
                existingKeys.add(compositeKey(c.AccountId, c.Email));
            }
        }

        // Walk records in order; first claim of a key wins, later ones are rejected
        Set<String> seenInBatch = new Set<String>();
        for (Contact c : contacts) {
            if (c.AccountId == null || c.Email == null) continue;

            String key = compositeKey(c.AccountId, c.Email);
            if (existingKeys.contains(key) || seenInBatch.contains(key)) {
                c.addError(ERROR_MSG);
            } else {
                seenInBatch.add(key);
            }
        }
    }

    // ─── Before Update ────────────────────────────────────────────────────────

    public void beforeUpdate(List<SObject> triggerNew, List<SObject> triggerOld) {
        List<Contact> newContacts = (List<Contact>) triggerNew;
        List<Contact> oldContacts = (List<Contact>) triggerOld;

        // Only consider records where Email or AccountId actually changed
        Set<Id> accountIds = new Set<Id>();
        for (Integer i = 0; i < newContacts.size(); i++) {
            Contact nc = newContacts.get(i);
            Contact oc = oldContacts.get(i);
            if (nc.AccountId != null && nc.Email != null
                && (nc.Email != oc.Email || nc.AccountId != oc.AccountId)) {
                accountIds.add(nc.AccountId);
            }
        }
        if (accountIds.isEmpty()) return;

        // Single SOQL: fetch all existing contacts on those accounts (including the records themselves)
        Map<String, Set<Id>> existingKeyToIds = new Map<String, Set<Id>>();
        for (Contact c : [
            SELECT Id, AccountId, Email
            FROM Contact
            WHERE AccountId IN :accountIds
        ]) {
            if (c.Email != null) {
                String key = compositeKey(c.AccountId, c.Email);
                if (!existingKeyToIds.containsKey(key)) {
                    existingKeyToIds.put(key, new Set<Id>());
                }
                existingKeyToIds.get(key).add(c.Id);
            }
        }

        // Walk records in order; first claim wins, later ones rejected
        Set<String> seenInBatch = new Set<String>();
        for (Integer i = 0; i < newContacts.size(); i++) {
            Contact nc = newContacts.get(i);
            Contact oc = oldContacts.get(i);

            // Skip records that weren't changed or don't have both fields
            if (nc.AccountId == null || nc.Email == null) continue;
            if (nc.Email == oc.Email && nc.AccountId == oc.AccountId) continue;

            String key = compositeKey(nc.AccountId, nc.Email);

            // Conflict with DB: another contact (not self) already holds this key
            Boolean conflictsWithDb = false;
            Set<Id> ids = existingKeyToIds.get(key);
            if (ids != null) {
                for (Id id : ids) {
                    if (id != nc.Id) {
                        conflictsWithDb = true;
                        break;
                    }
                }
            }

            // Conflict within this batch: an earlier record in the list already claimed this key
            Boolean conflictsWithBatch = seenInBatch.contains(key);

            if (conflictsWithDb || conflictsWithBatch) {
                nc.addError(ERROR_MSG);
            } else {
                seenInBatch.add(key);
            }
        }
    }

    // ─── Helper ───────────────────────────────────────────────────────────────

    private static String compositeKey(Id accountId, String email) {
        return accountId + '|' + String.lowerCase(email);
    }
}
```

